47: static void parse_cpu_part(const char *cpu_part_start, const char *cpu_part_end,
48:                            struct cpuinfo_arm_linux_processor *processor) {
49:     const size_t cpu_part_length = (size_t)(cpu_part_end - cpu_part_start);
50: 
51:     /*
52:      * CPU part should contain hex prefix (0x) and one to three hex digits.
53:      * I have never seen less than three digits as a value of this field,
54:      * but I don't think it is impossible to see such values in future.
55:      * Value can not contain more than three hex digits since
56:      * Main ID Register (MIDR) assigns only a 12-bit value for CPU part.
57:      */
58:     if (cpu_part_length < 3 || cpu_part_length > 5) {
59:         return;
60:     }
61: 
62:     /* Verify the presence of hex prefix */
63:     if (cpu_part_start[0] != '0' || cpu_part_start[1] != 'x') {
64:         return;
65:     }
66: 
67:     /* Verify that characters after hex prefix are hexadecimal digits and decode them */
68:     uint32_t cpu_part = 0;
